#!/bin/bash
# wag-start.sh — starts server + ngrok with proper permissions
# Called by Week at a Glance.app via Terminal so Full Disk Access is inherited

SYSCONF="$HOME/Library/Application Support/ngrok/ngrok.yml"
WAGCONF="$HOME/Desktop/wag-ngrok.yml"
PORT=8788

# Kill any stale processes
pkill -f "wag-server.py"  2>/dev/null
pkill -f "ngrok.*week-at-a-glance" 2>/dev/null
sleep 1

# Start server
nohup python3 "$HOME/Desktop/wag-server.py" > /tmp/wag-server.log 2>&1 &

# Wait for it
for i in $(seq 1 10); do
  sleep 0.5
  lsof -ti tcp:$PORT > /dev/null 2>&1 && break
done

# Start ngrok
nohup ngrok start \
  --config "$SYSCONF" \
  --config "$WAGCONF" \
  week-at-a-glance > /tmp/wag-ngrok.log 2>&1 &

echo "✓ Week at a Glance is running"
echo "→ $( sleep 3 && curl -s http://localhost:4040/api/tunnels | python3 -c "import sys,json; t=json.load(sys.stdin)['tunnels']; print(t[0]['public_url'] if t else 'http://localhost:$PORT')" 2>/dev/null || echo "http://localhost:$PORT" )"
